const cases = [
  { input: '카드가 두 번 결제됐어요', want: 'payment' },
  { input: '언제 도착하나요', want: 'shipping' },
];

let ok = 0;
for (const c of cases) {
  const got = JSON.parse(await classify(c.input)).category;
  if (got === c.want) ok++;
  else console.log('틀림:', c.input, '→', got);
}
console.log(`정확도 ${(ok / cases.length * 100).toFixed(1)}%`);
